#include <iostream>
#include <iomanip>
using namespace std;

int main() {
  int A, B;
  cin >> A >> B;
  // std::fixed -> 固定小数点で出力することを指定
  // std::setprecision(int n) -> 小数点以下 n 桁で出力することを指定
  cout << fixed << setprecision(2);
  cout << A * B / 100.0 << '\n';
  return 0;
}

#include <iostream>

int main(){
  int A, B;
  std::cin >> A >> B;
  std::cout << A * B / 100.0 << std::endl;
  return 0;
}

#include <iostream>
#include <iomanip>

int main(){
  int A, B;
  std::cin >> A >> B;
  std::cout << std::scientific << std::setprecision(5);
  std::cout << A * B / 100.0 << std::endl;
  return 0;
}
